  "decision.pv_first_with_battery_topup": s("{name} adds battery output to its PV share because PV alone does not cover the target.", "{name} ergänzt seinen PV-Anteil aus dem Akku, weil PV allein das Ziel nicht deckt.", "{name} vult zijn PV-aandeel aan uit de batterij, omdat PV alleen het doel niet dekt.", "{name} complète sa part PV par la batterie, car le PV seul ne suffit pas."),
  "decision.solar_plus_battery_discharge": s("{name} supplies its PV and the battery covers the rest of its share.", "{name} liefert sein PV, der Akku deckt den Rest seines Anteils.", "{name} levert zijn PV en de batterij dekt de rest van zijn aandeel.", "{name} fournit son PV et la batterie couvre le reste de sa part."),
  "decision.night_min_soc_idle": s("{name} is parked at the minimum output while the batteries rest at their minimum SoC.", "{name} steht auf Mindestausgang, während die Akkus auf Min-SoC ruhen.", "{name} staat op minimale uitgang terwijl de batterijen op minimum-SoC rusten.", "{name} reste au minimum de sortie pendant que les batteries sont au SoC minimum."),
  "decision.ac_charge_allocation": s("{name} is charging from surplus, taking a share of it weighted by the room left in its battery.", "{name} lädt aus dem Überschuss, mit einem Anteil nach dem freien Platz im Akku.", "{name} laadt uit het overschot, met een aandeel naar de vrije ruimte in de batterij.", "{name} se charge avec le surplus, selon la place restante dans sa batterie."),
  "decision.ac_charge_share_too_small": s("{name} may charge, but its share of this surplus was too small to be worth changing direction for, so it went to the other devices.", "{name} dürfte laden, aber sein Anteil war zu klein für einen Richtungswechsel, daher ging er an die anderen Geräte.", "{name} mag laden, maar zijn aandeel was te klein voor een richtingswissel en ging naar de andere apparaten.", "{name} pourrait charger, mais sa part était trop faible pour changer de sens ; elle est allée aux autres appareils."),
  "decision.ac_charge_no_ceiling": s("{name} may charge, but has no charge limit to charge at: it reports 0, or reports none and its model carries no rating.", "{name} dürfte laden, hat aber keine Ladegrenze: Es meldet 0 oder keine, und sein Modell hat keinen Nennwert.", "{name} mag laden, maar heeft geen laadlimiet: het meldt 0 of niets en het model heeft geen nominale waarde.", "{name} pourrait charger mais n’a pas de limite de charge : il signale 0 ou rien, et son modèle n’a pas de valeur nominale."),
  "decision.ac_charge_not_permitted": s("{name} is not charging this cycle: its model has no AC charge path, charging is switched off for it, or its battery is full, drained by another load or unavailable.", "{name} lädt in diesem Zyklus nicht: Sein Modell kann nicht AC-laden, Laden ist ausgeschaltet, oder der Akku ist voll, wird anderweitig entladen oder ist nicht verfügbar.", "{name} laadt deze cyclus niet: het model kan niet AC-laden, laden staat uit, of de batterij is vol, wordt elders ontladen of is niet beschikbaar.", "{name} ne charge pas ce cycle : son modèle n’a pas de charge AC, la charge est désactivée, ou sa batterie est pleine, déchargée ailleurs ou indisponible."),
  "decision.ac_charge_held_by_full_charge_assist": s("{name} takes no share of the surplus: the full-charge assist holds it, for its own charge or the restore after it.", "{name} bekommt keinen Anteil am Überschuss: Die Vollladehilfe hält es für ihre eigene Ladung oder die Wiederherstellung danach.", "{name} krijgt geen aandeel in het overschot: de volledig-ladenhulp houdt het vast voor de eigen lading of het herstel daarna.", "{name} ne prend aucune part du surplus : l’aide à la charge complète le retient."),

  "runtime.title": s("Runtime settings", "Laufzeiteinstellungen", "Runtime-instellingen", "Réglages d’exécution"),
  "runtime.sub": s("Changes are checked by the EMS and take effect in the next control loop", "Änderungen prüft das EMS; sie wirken in der nächsten Regelschleife", "Wijzigingen worden door het EMS gecontroleerd en werken in de volgende regellus", "Les changements sont vérifiés par l’EMS et prennent effet au cycle suivant"),
  "runtime.notConfigured": s("Read-only. No dashboard password is set, so runtime values cannot be changed here.", "Nur lesen. Es ist kein Dashboard-Passwort gesetzt, daher lassen sich Laufzeitwerte hier nicht ändern.", "Alleen lezen. Er is geen dashboardwachtwoord ingesteld, dus runtime-waarden kunnen hier niet worden gewijzigd.", "Lecture seule. Aucun mot de passe n’est défini, les valeurs ne peuvent pas être modifiées ici."),
  "runtime.signIn": s("Read-only. Sign in to change runtime values.", "Nur lesen. Melde dich an, um Laufzeitwerte zu ändern.", "Alleen lezen. Meld je aan om runtime-waarden te wijzigen.", "Lecture seule. Connectez-vous pour modifier les valeurs."),
