  "runtime.warn.systemOff": s("Turn the EMS off? It stops writing to every inverter; each keeps its last output limit until the EMS is on again. A charge the EMS started gets one command that ends it.", "Das EMS ausschalten? Es schreibt nichts mehr an die Wechselrichter; jeder behält seine letzte Ausgangsgrenze, bis das EMS wieder an ist. Eine vom EMS gestartete Ladung bekommt einen Befehl, der sie beendet.", "Het EMS uitzetten? Het schrijft niets meer naar de omvormers; elke omvormer houdt zijn laatste uitgangslimiet tot het EMS weer aan staat. Een door het EMS gestarte lading krijgt één opdracht die haar beëindigt.", "Désactiver l’EMS ? Il n’écrit plus vers les onduleurs ; chacun garde sa dernière limite jusqu’à la réactivation. Une charge lancée par l’EMS reçoit une commande qui l’arrête."),
  "runtime.warn.systemOffKept": s("The device settings it keeps stay as they are on the inverters while it is off; once it is on, it sets them again as you set them.", "Die gehaltenen Geräteeinstellungen bleiben auf den Wechselrichtern, solange es aus ist; danach setzt es sie wieder wie eingestellt.", "De vastgehouden apparaatinstellingen blijven op de omvormers zolang het uit staat; daarna zet het ze weer zoals ingesteld.", "Les réglages maintenus restent sur les onduleurs pendant l’arrêt ; ensuite il les réapplique."),
  "runtime.warn.deviceOff": s("Take {device} out of EMS control? The EMS writes nothing more to it, and it keeps its last output limit until you enable it again. A charge the EMS started on it gets one command that ends it.", "{device} aus der EMS-Regelung nehmen? Das EMS schreibt nichts mehr daran, und es behält seine letzte Ausgangsgrenze, bis du es wieder aktivierst. Eine vom EMS gestartete Ladung bekommt einen Befehl, der sie beendet.", "{device} uit de EMS-regeling halen? Het EMS schrijft er niets meer naar en het houdt zijn laatste uitgangslimiet tot je het weer inschakelt. Een door het EMS gestarte lading krijgt één opdracht die haar beëindigt.", "Retirer {device} du pilotage EMS ? L’EMS n’y écrit plus rien et il garde sa dernière limite jusqu’à sa réactivation. Une charge lancée par l’EMS reçoit une commande qui l’arrête."),
  "runtime.warn.settingsSavedForLater": s("The {settings} are saved and written once you enable {device} again.", "{settings} werden gespeichert und geschrieben, sobald du {device} wieder aktivierst.", "{settings} worden opgeslagen en geschreven zodra je {device} weer inschakelt.", "{settings} sont enregistrés et écrits à la réactivation de {device}."),
  "runtime.warn.settingsLeft": s("Its {settings} stay as they are on the inverter while the EMS does not control {device}.", "{settings} bleiben auf dem Wechselrichter, solange das EMS {device} nicht regelt.", "{settings} blijven op de omvormer zolang het EMS {device} niet regelt.", "{settings} restent sur l’onduleur tant que l’EMS ne pilote pas {device}."),
  "runtime.warn.settingsHanded": s("The EMS writes nothing for {settings} from now on; the inverter and the Zendure app decide.", "Für {settings} schreibt das EMS ab jetzt nichts; Wechselrichter und Zendure-App entscheiden.", "Voor {settings} schrijft het EMS voortaan niets; de omvormer en de Zendure-app beslissen.", "L’EMS n’écrit plus rien pour {settings} ; l’onduleur et l’application Zendure décident."),
  "runtime.warn.settingsQuestion": s("Change {settings} of {device}?", "{settings} von {device} ändern?", "{settings} van {device} wijzigen?", "Modifier {settings} de {device} ?"),
  "runtime.warn.settingsKept": s("The EMS writes {settings} to the inverter and keeps them there.", "Das EMS schreibt {settings} an den Wechselrichter und hält sie dort.", "Het EMS schrijft {settings} naar de omvormer en houdt ze daar.", "L’EMS écrit {settings} sur l’onduleur et les y maintient."),
  "runtime.warn.autoHeatOff": s("With battery heating off, the battery does not warm itself in the cold.", "Mit ausgeschalteter Akkuheizung wärmt sich der Akku bei Kälte nicht selbst.", "Met batterijverwarming uit warmt de batterij zichzelf niet op bij kou.", "Sans chauffage, la batterie ne se réchauffe pas par temps froid."),
  "runtime.warn.acInput": s("Switch {device} to AC charging? The EMS stops regulating its output and lets it charge from the grid at the AC charge power.", "{device} auf AC-Laden umstellen? Das EMS regelt seinen Ausgang nicht mehr und lässt es mit der AC-Ladeleistung aus dem Netz laden.", "{device} omzetten naar AC-laden? Het EMS regelt de uitgang niet meer en laat het laden uit het net met het AC-laadvermogen.", "Passer {device} en charge AC ? L’EMS cesse de réguler sa sortie et le laisse charger depuis le réseau."),
  "runtime.warn.acOutput": s("Switch {device} back to output?", "{device} wieder auf Ausgang stellen?", "{device} terugzetten naar uitgang?", "Repasser {device} en sortie ?"),
  "runtime.warn.offgrid": s("Change the off-grid socket of {device}? The EMS writes the new mode to the inverter.", "Die Notstromsteckdose von {device} ändern? Das EMS schreibt den neuen Modus an den Wechselrichter.", "Het noodstroomstopcontact van {device} wijzigen? Het EMS schrijft de nieuwe modus naar de omvormer.", "Modifier la prise hors réseau de {device} ? L’EMS écrit le nouveau mode sur l’onduleur."),
  "runtime.warn.emsOff": s("The EMS is off, so this takes effect once it is on again.", "Das EMS ist aus; das wirkt, sobald es wieder an ist.", "Het EMS staat uit; dit werkt zodra het weer aan staat.", "L’EMS est désactivé ; cela prendra effet à sa réactivation."),
  "runtime.warn.deviceOutside": s("{device} is out of EMS control, so this takes effect once you enable it again.", "{device} ist außerhalb der EMS-Regelung; das wirkt, sobald du es wieder aktivierst.", "{device} valt buiten de EMS-regeling; dit werkt zodra je het weer inschakelt.", "{device} est hors pilotage ; cela prendra effet à sa réactivation."),
  "runtime.warn.bothOff": s("The EMS is off and {device} is out of EMS control, so this takes effect once the EMS is on and you enable {device} again.", "Das EMS ist aus und {device} außerhalb der Regelung; das wirkt, sobald das EMS an ist und du {device} wieder aktivierst.", "Het EMS staat uit en {device} valt buiten de regeling; dit werkt zodra het EMS aan staat en je {device} weer inschakelt.", "L’EMS est désactivé et {device} hors pilotage ; cela prendra effet quand l’EMS sera actif et {device} réactivé."),
  "runtime.warn.stopChargeInApp": s("To stop a charge meanwhile, use the Zendure app.", "Um eine Ladung vorher zu stoppen, nutze die Zendure-App.", "Gebruik de Zendure-app om een lading intussen te stoppen.", "Pour arrêter une charge entre-temps, utilisez l’application Zendure."),
